import sys
from collections import Counter

def days_in_month(month, year):
    if month in {1, 3, 5, 7, 8, 10, 12}:
        return 31
    elif month in {4, 6, 9, 11}:
        return 30
    else:
        return 28

def main():
    prophecy = sys.stdin.read().strip()
    date_counts = Counter(prophecy[i:i+10] for i in range(len(prophecy) - 9))
    max_count = 0
    apocalypse_date = ""
    for date, count in date_counts.items():
        if date[2] == '-' and date[5] == '-':
            day = int(date[:2])
            month = int(date[3:5])
            year = int(date[6:])
            if 2013 <= year <= 2015 and 1 <= month <= 12 and 1 <= day <= days_in_month(month, year):
                if count > max_count:
                    max_count = count
                    apocalypse_date = date
    print(apocalypse_date)

main()
